using System.Net;
using System.Net.Http.Json;

namespace sv_c45d9db94124492885d708156f85f8c9.Client.Services;

public sealed class ShipmentServiceClient(HttpClient http) : IShipmentService
{
    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment '{trackingNumber}' was not found.");
        }

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct)
               ?? throw new InvalidOperationException("Received null response from server.");
    }
}

